RSpec.describe Timekeeping::LocalOwner, "reservation landing during the row lock", committed_data: true do
  # "Add committed, two-connection examples that prove three required guarantees: a handoff waits until
  # LocalOwner commits; an employee update waiting behind a reservation insert refuses the now-reserved
  # entry; and a second outbox writer cannot commit past a paused first writer."
  # Only an employee-primary update is refused on a reserved entry, so the 403 is the answer that
  # changes with the reservation read after the row-lock wait.
  it "refuses an employee update that waited on an uncommitted reservation insert once the insert commits" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation.to_s
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
      duration: 30.0, note: "before", bill_status: "unbilled"
    )
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    inserted = Queue.new
    commit = Queue.new
    reservation_pids = Queue.new
    update_pids = Queue.new

    reservation = committed_data_thread(reservation_pids) do
      ActiveRecord::Base.transaction do
        ApplicationRecord.connection.execute(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, company.id, entry.id, 1, SecureRandom.uuid, "committed", "active"]))
          INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
          VALUES (?, ?, ?, ?, ?, ?, NOW())
        SQL
        inserted << true
        commit.pop
      end
    end
    expect(inserted.pop(timeout: 5)).to be(true), "the reservation insert never ran"

    update = committed_data_thread(update_pids) do
      described_class.call(
        operation: :update, company_id: company.id, generation:,
        actor: described_class::Actor.user(user_id: user.id, role: "employee"),
        params: { "idempotency_key" => "waits-on-reservation", "entry_id" => entry.id, "body" => { "note" => "after" } }
      )
    end

    begin
      blocked = blocked_by?(update_pids.pop(timeout: 5), reservation_pids.pop(timeout: 5))
    ensure
      commit << true
    end

    expect(blocked).to be(true), "the employee update never waited on the reservation insert"
    reservation.join(5)
    outcome = update.join(5)&.value
    expect([outcome&.status, outcome&.body]).to eq([403, { "reason" => "forbidden" }])
    entry.reload
    expect([entry.note, entry.version]).to eq(["before", 1])
    expect(count.call("entry_audits")).to eq(0)
    expect(count.call("entry_outbox_items")).to eq(0)
    expect(count.call("idempotency_records")).to eq(0)
  ensure
    commit&.push(true)
    [reservation, update].compact.each { |thread| thread.join(5) }
  end
end

