RSpec.describe Timekeeping::LocalOwner, "when two writers reach the outbox", committed_data: true do
  # "Add committed, two-connection examples that prove three required guarantees: a handoff waits until
  # LocalOwner commits; an employee update waiting behind a reservation insert refuses the now-reserved
  # entry; and a second outbox writer cannot commit past a paused first writer."
  # The writers update different entries with different keys, so the outbox lock is the only lock they
  # share. Position order alone would read first-then-second even without that lock, because the first
  # writer draws its position before it pauses; the wait and the empty committed outbox prove the lock.
  it "keeps a second outbox writer from committing while the first writer is paused holding the outbox lock" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation.to_s
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    first_entry, second_entry = %w[first second].map do |note|
      Timekeeping::LocalEntry.create!(
        company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current,
        duration: 30.0, note:, bill_status: "unbilled"
      )
    end
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    pause_step = described_class::STEPS.find { |step| step == :outbox_written }
    raise ArgumentError, "outbox_written is not a LocalOwner step" if pause_step.nil?

    entered = Queue.new
    release = Queue.new
    first_pids = Queue.new
    second_pids = Queue.new
    first_params = { "idempotency_key" => "outbox-first", "entry_id" => first_entry.id, "body" => { "note" => "first after" } }
    call_owner = lambda do |params, checkpoint|
      described_class.call(
        operation: :update, company_id: company.id, generation:,
        actor: described_class::Actor.user(user_id: user.id, role: "employee"), params:, checkpoint:
      )
    end
    pause = lambda do |step|
      next unless step == pause_step

      entered << true
      release.pop
    end
    first = committed_data_thread(first_pids) { call_owner.call(first_params, pause) }
    expect(entered.pop(timeout: 5)).to be(true), "the first writer never paused after its outbox insert"

    second = committed_data_thread(second_pids) do
      call_owner.call(
        { "idempotency_key" => "outbox-second", "entry_id" => second_entry.id, "body" => { "note" => "second after" } },
        ->(_step) { }
      )
    end

    begin
      blocked = blocked_by?(second_pids.pop(timeout: 5), first_pids.pop(timeout: 5))
      committed_while_paused = count.call("entry_outbox_items")
    ensure
      release << true
    end

    expect(blocked).to be(true), "the second writer never waited on the first writer's outbox lock"
    expect(committed_while_paused).to eq(0)
    first_outcome = first.join(5)&.value
    second_outcome = second.join(5)&.value
    expect([first_outcome.status, second_outcome.status]).to eq([200, 200])
    expect(Timekeeping::LocalOutboxEntry.order(:outbox_position).pluck(:entry_id)).to eq([first_entry.id, second_entry.id])

    # A retry of the delivered first request replays its answer and adds no second outbox row.
