  let(:project) { create(:project, client: create(:client, company:)) }

  before do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    create(:employment, company:, user: employee)
    employee.add_role("employee", company)
  end

  # The step is taken from LocalOwner::STEPS, so renaming it fails here
  # instead of leaving a pause that never fires.
  def pause_outbox_writer_at(step_name, entered, release)
    step = described_class::STEPS.find { |candidate| candidate == step_name }
    raise ArgumentError, "#{step_name} is not a LocalOwner step" if step.nil?

    lambda do |reached|
      next unless reached == step

      entered << true
      release.pop
    end
  end

  # "a second outbox writer cannot commit past a paused first writer"
  # The writers update different entries with different keys, so the outbox
  # lock is the only lock they share. Position order alone would read
  # [first, second] even without that lock, so the wait and the uncommitted
  # second row are the proof.
  it "holds a second writer's outbox row back until a first writer paused after its outbox insert commits" do
    generation = TimekeepingOwnership.current.generation.to_s
    first_entry, second_entry = %w[first second].map do |note|
      Timekeeping::LocalEntry.create!(
        company_id: company.id, user_id: employee.id, project_id: project.id, work_date: Date.current,
        duration: 30.0, note:, bill_status: "unbilled"
      )
    end
    actor = described_class::Actor.user(user_id: employee.id, role: "employee")
    company_id = company.id
    entered = Queue.new
    release = Queue.new
    first_pids = Queue.new
    second_pids = Queue.new
    checkpoint = pause_outbox_writer_at(:outbox_written, entered, release)

    first = committed_data_thread(first_pids) do
      described_class.call(
        operation: :update, company_id:, generation:, actor:,
        params: { "idempotency_key" => "outbox-first", "entry_id" => first_entry.id, "body" => { "note" => "first after" } },
        checkpoint:
      )
    end
    expect(entered.pop(timeout: 5)).to be(true), "the first write never paused after its outbox insert"

    second = committed_data_thread(second_pids) do
      described_class.call(
        operation: :update, company_id:, generation:, actor:,
        params: { "idempotency_key" => "outbox-second", "entry_id" => second_entry.id, "body" => { "note" => "second after" } }
      )
    end

    begin
      blocked = blocked_by?(second_pids.pop(timeout: 5), first_pids.pop(timeout: 5))
      committed_while_paused = ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM entry_outbox_items").to_i
    ensure
      release << true
    end

    expect(blocked).to be(true), "the second write never waited on the first write's outbox lock"
    expect(committed_while_paused).to eq(0)
    expect(first.join(5)&.value&.status).to eq(200)
    expect(second.join(5)&.value&.status).to eq(200)
    expect(Timekeeping::LocalOutboxEntry.order(:outbox_position).pluck(:entry_id)).to eq([first_entry.id, second_entry.id])
  ensure
    release&.push(true)
    [first, second].compact.each { |thread| thread.join(5) }
  end
end

require "rails_helper"

RSpec.describe Timekeeping::LocalOwner, "write queued behind an uncommitted handoff", committed_data: true do
  # "Test the generation lock during a concurrent handoff."
  # The handoff updates the ownership row first and holds its transaction open.
  # A write that read its pre-wait snapshot would be admitted past the fence.
  it "refuses with stale_generation a write that queued behind an uncommitted handoff and stores no row" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation.to_s
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current, duration: 30.0,
      note: "before", bill_status: "unbilled"
    )
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    updated = Queue.new
    commit = Queue.new
    handoff_pids = Queue.new
    writer_pids = Queue.new

    handoff = committed_data_thread(handoff_pids) do
      ActiveRecord::Base.transaction do
        TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "close_admission")
        updated << true
        commit.pop
      end
    end
    expect(updated.pop(timeout: 5)).to be(true), "the handoff update never started"

    writer = committed_data_thread(writer_pids) do
      described_class.call(
        operation: :update, company_id: company.id, generation:,
        actor: described_class::Actor.user(user_id: user.id, role: "employee"),
        params: { "idempotency_key" => "behind-handoff", "entry_id" => entry.id, "body" => { "note" => "after" } }
      )
    end

    begin
      blocked = blocked_by?(writer_pids.pop(timeout: 5), handoff_pids.pop(timeout: 5))
    ensure
      commit << true
    end

    expect(blocked).to be(true), "the write never waited on the handoff's uncommitted update"
    outcome = writer.join(5)&.value
    expect([outcome&.status, outcome&.body]).to eq([409, { "reason" => "stale_generation" }])
    entry.reload
    expect([entry.note, entry.version]).to eq(["before", 1])
    expect(%w[entry_audits entry_outbox_items idempotency_records].map { |table| count.call(table) }).to eq([0, 0, 0])
  ensure
    commit << true
    [handoff, writer].compact.each { |thread| thread.join(5) }
    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: nil)
  end
end

require "rails_helper"

RSpec.describe Timekeeping::LocalOwner, "update waiting behind a reservation insert", committed_data: true do
  # "Add committed, two-connection examples that prove three required guarantees: a handoff waits until LocalOwner commits; an employee update waiting behind a reservation insert refuses the now-reserved entry; and a second outbox writer cannot commit past a paused first writer."
  # The reservation insert holds a key-share lock on the entry row through its
  # foreign key, so the update's row lock waits on it. Only the refusal can
  # catch a reservation flag read from the snapshot taken before that wait.
  it "refuses an employee update that waited behind a reservation insert once that insert commits" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation.to_s
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current, duration: 30.0,
      note: "before", bill_status: "unbilled"
    )
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    inserted = Queue.new
    commit = Queue.new
    reservation_pids = Queue.new
    update_pids = Queue.new

    reservation = committed_data_thread(reservation_pids) do
      ActiveRecord::Base.transaction do
        ApplicationRecord.connection.execute(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, company.id, entry.id, 1, SecureRandom.uuid, "committed", "active"]))
          INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
          VALUES (?, ?, ?, ?, ?, ?, NOW())
        SQL
        inserted << true
        commit.pop
      end
    end
    expect(inserted.pop(timeout: 5)).to be(true), "the reservation insert never ran"

    update = committed_data_thread(update_pids) do
      described_class.call(
        operation: :update, company_id: company.id, generation:,
        actor: described_class::Actor.user(user_id: user.id, role: "employee"),
        params: { "idempotency_key" => "behind-reservation", "entry_id" => entry.id, "body" => { "note" => "after" } }
      )
    end

    begin
      blocked = blocked_by?(update_pids.pop(timeout: 5), reservation_pids.pop(timeout: 5))
    ensure
      commit << true
    end

    expect(blocked).to be(true), "the update never waited on the uncommitted reservation insert"
    outcome = update.join(5)&.value
    expect([outcome&.status, outcome&.body]).to eq([403, { "reason" => "forbidden" }])
    entry.reload
    expect([entry.note, entry.version]).to eq(["before", 1])
    expect(%w[entry_audits entry_outbox_items idempotency_records].map { |table| count.call(table) }).to eq([0, 0, 0])
  ensure
    commit << true
    [reservation, update].compact.each { |thread| thread.join(5) }
  end
end

require "rails_helper"

RSpec.describe Timekeeping::LocalOwner, "second outbox writer behind a paused first writer", committed_data: true do
  # "Add committed, two-connection examples that prove three required guarantees: a handoff waits until LocalOwner commits; an employee update waiting behind a reservation insert refuses the now-reserved entry; and a second outbox writer cannot commit past a paused first writer."
  # The writers update different entries with different keys, so the outbox
  # lock is the only lock they share. The first writer has already drawn its
  # outbox position, so position order alone would look right even without
  # the lock: the proof is the wait and the uncommitted second row.
  it "keeps a second outbox writer from committing while the first writer is paused after its outbox insert" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation.to_s
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    first_entry, second_entry = %w[first second].map do |note|
      Timekeeping::LocalEntry.create!(
        company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.current, duration: 30.0,
        note:, bill_status: "unbilled"
      )
    end
    count = ->(table) { ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i }
    pause_step = described_class::STEPS.find { |step| step == :outbox_written }
    raise ArgumentError, "outbox_written is not a LocalOwner step" if pause_step.nil?

    entered = Queue.new
    release = Queue.new
    first_pids = Queue.new
    second_pids = Queue.new
    pause_after_outbox = lambda do |step|
      next unless step == pause_step

      entered << true
      release.pop
    end
    call_update = lambda do |entry, key, checkpoint|
      described_class.call(
        operation: :update, company_id: company.id, generation:,
        actor: described_class::Actor.user(user_id: user.id, role: "employee"),
        params: { "idempotency_key" => key, "entry_id" => entry.id, "body" => { "note" => "#{key} changed" } },
        checkpoint:
      )
    end

    first = committed_data_thread(first_pids) { call_update.call(first_entry, "first-writer", pause_after_outbox) }
    expect(entered.pop(timeout: 5)).to be(true), "the first writer never paused at outbox_written"

    second = committed_data_thread(second_pids) { call_update.call(second_entry, "second-writer", ->(_step) { }) }

    begin
      blocked = blocked_by?(second_pids.pop(timeout: 5), first_pids.pop(timeout: 5))
      committed_while_paused = count.call("entry_outbox_items")
    ensure
      release << true
    end

    expect(blocked).to be(true), "the second writer never waited on the first writer's outbox lock"
    expect(committed_while_paused).to eq(0)
    outcomes = [first, second].map { |thread| thread.join(5)&.value&.status }
    expect(outcomes).to eq([200, 200])
    expect(Timekeeping::LocalOutboxEntry.order(:outbox_position).pluck(:entry_id)).to eq([first_entry.id, second_entry.id])
  ensure
    release << true
    [first, second].compact.each { |thread| thread.join(5) }
  end
end
